        default_config,
        '{workflow,steps,plan_site,config,prompt_template}',
        to_jsonb(
            replace(
                replace(
                    default_config#>>'{workflow,steps,plan_site,config,prompt_template}',
                    'orphans the page from all of it.',
                    'orphans the page from all of it.' || E'\n\n' ||
                    'Directory rule: content_features may carry one or more global directory keys - model_directory, adoption_tracker, protocol_tracker, mortgage_lender_directory, savings_provider_directory, health_insurer_directory. ... (a) add the matching SECTION component to the homepage sections array ... (b) when that key also has separate_page=true, plan exactly ONE dedicated page whose name and page_type are BOTH the exact value listed here ... mortgage_lender_directory uses mortgage-lenders ... Compose that page with populated sections in this order: hero, then the LISTING component ..., then call-to-action; set in_header and in_footer true. ... Do NOT plan a directory page or section for a kind whose key is absent or not recommended.'
                ),
                'When no Verified Facts are listed, use plain strings only.',
                'When no Verified Facts are listed, use plain strings only.' || E'\n' ||
                '18. If the classification data includes any content_features directory key (...) with recommended = true, apply the Directory rule above: the matching section component on the homepage, and when separate_page = true, the dedicated page with its exact name, exact page_type, and hero + listing + call-to-action sections'
            )
        )
    ),
    updated_at = NOW()
WHERE type = 'build-site-planner' AND is_active
  AND COALESCE(is_snapshot, false) = false AND deleted_at IS NULL
  AND default_config#>>'{workflow,steps,plan_site,config,prompt_template}' LIKE '%orphans the page from all of it.%'
  AND default_config#>>'{workflow,steps,plan_site,config,prompt_template}' LIKE '%When no Verified Facts are listed, use plain strings only.%'
  AND default_config#>>'{workflow,steps,plan_site,config,prompt_template}' NOT LIKE '%Directory rule:%';

DO $do$   -- verify: DO/RAISE, because a SELECT cannot stop the COMMIT
DECLARE p text;
BEGIN
    SELECT default_config#>>'{workflow,steps,plan_site,config,prompt_template}' INTO p
    FROM agent_definitions WHERE type = 'build-site-planner' AND is_active
      AND COALESCE(is_snapshot, false) = false AND deleted_at IS NULL;
    IF (length(p) - length(replace(p, 'Directory rule:', ''))) / length('Directory rule:') <> 1 THEN
